circle.normalizedSource:
"use geosolve sketch";
import { sketch, mm } from "@geosolve/sketch-code";

export default sketch(($) => {
  const bore = $.geometry.centerRadiusCircle("bore", {
    center: [0, 0],
    radius: mm(2),
  });
  const geometry1 = $.geometry.centerRadiusCircle("geometry1", {
    center: [40, 40],
    label: "center-radius-circle-0000000000000002",
    radius: mm(10),
    role: "profile",
  });
  $.group("Canvas additions", [geometry1]);
  return {
    bore: bore,
  };
});

inferred.normalizedSource:
"use geosolve sketch";
import { sketch, mm } from "@geosolve/sketch-code";

export default sketch(($) => {
  const bore = $.geometry.centerRadiusCircle("bore", {
    center: [0, 0],
    radius: mm(2),
  });
  const segment1 = $.geometry.segment("segment1", {
    branchDirection: [1, 0],
    end: [20, 0],
    label: "segment-0000000000000002",
    role: "profile",
    start: bore.center,
  });
  const constraint2 = $.constraint.horizontal("constraint2", {
    label: "segment-0000000000000002-relation-0000",
    span: segment1.span,
  });
  $.group("Canvas additions", [segment1, constraint2]);
  return {
    bore: bore,
  };
});

